      whatidoCleanup?.();
      skillsCleanup?.();
    };
  },[]);

  return <>
    {/* Ambient drifting light — slow, very low contrast, sits under everything */}
    <div className="soft-ambience" aria-hidden="true"><i /><i /><i /></div>

    {/* Static drafting grid. This previously tracked the cursor via React
