    </section>

    <div className="tech-marquee">
      <div className="tech-marquee-track">
        {[...TECH,...TECH].map((t,i)=><span key={i} className="tech-marquee-item">{t.name}<span style={{marginLeft:16,opacity:.35}}>·</span></span>)}
      </div>
    </div>

    {/* ABOUT */}
    <section ref={aboutRef} id="about" className="about-section light-section-shell section-about" style={{position:"relative"}}>
      <div style={{maxWidth:1200,margin:"0 auto"}}>
        <div className="sec-head sec-head-center">
          <span className="sec-eyebrow">About</span>
          <h2 className="section-title">Who I Am</h2>
        </div>
        <div className="split-block about-copy-panel">
          <div style={{padding:"20px 0"}}>
            <p className="about-paragraph" style={{color:theme.text,opacity:.9}}>
              I'm <strong style={{color:theme.accent}}>Michael Gaitho</strong>, a Frontend Developer & UI/UX designer specializing in AI-powered interfaces and real-time analytics. I build AI-powered web interfaces and dashboards, leading frontend architecture and UI/UX design decisions. I hold a Bachelor of IT, specializing in software engineering and human-computer interaction.
            </p>
          </div>
          <div className="about-buttons"><button className="bp" onClick={() => window.open('/resume.pdf', '_blank')}>Download Resume</button><button className="bg" onClick={()=>scrollTo("projects")}>See Work →</button></div>
        </div>
      </div>
      {devMode&&<DevBadge id="about" devMode={devMode} theme={theme}/>}
    </section>

    {/* WHAT I DO — pinned horizontal case-study rail */}
    <section ref={designSectionRef} id="what-i-do" className="whatido-section light-section-shell section-whatido">
      <div ref={aboutRailRef} className="whatido-horizontal-rail">
        <div ref={aboutTrackRef} className="whatido-horizontal-track">
          {CAPABILITIES.map((item, i) => (
            <article
              key={item.id}
              className={`cap-card tone-${item.tone} cap-variant-${item.variant} ${i === activeWhatIDo ? "is-active" : ""}`}
            >
              <div className="cap-card-inner">
                <div className="cap-copy">
                  <div className="cap-meta">
                    <span className="cap-index">{item.id}</span>
                    <span className="cap-meta-rule" />
                    <span className="cap-kicker">{item.kicker}</span>
                  </div>
                  <h3 className="cap-title">{item.title}</h3>
                  <p className="cap-desc">{item.desc}</p>
                  <ul className="cap-tags">
                    {item.tags.map((tag) => <li key={tag}>{tag}</li>)}
                  </ul>
                  <div className="cap-deliverable">
                    <span className="cap-deliverable-label">Deliverable</span>
                    <span className="cap-deliverable-value">{item.deliverable}</span>
                  </div>
                </div>
                <div className="cap-visual">
                  <CapabilityVisual variant={item.variant} />
                </div>
              </div>
            </article>
          ))}
        </div>
      </div>

      {/* Fixed chapter index — stays put while the rail travels underneath */}
      <div className="cap-dock">
        <div className="cap-dock-left">
          <span className="cap-dock-label">What I do</span>
          <span className="cap-dock-title">{activeCapability.title}</span>
        </div>
        <nav className="cap-dock-nav" aria-label="Capabilities">
          {CAPABILITIES.map((item, i) => (
            <button
              key={item.id}
              type="button"
              className={`cap-dock-dot${i === activeWhatIDo ? " is-active" : ""}`}
              aria-label={item.title}
              aria-current={i === activeWhatIDo ? "true" : undefined}
              onClick={() => goToCapability(i)}
            >
              <span>{item.id}</span>
            </button>
          ))}
        </nav>
        <div className="cap-dock-right">
          <span className="cap-dock-count">
            {activeCapability.id} <i>/</i> {String(CAPABILITIES.length).padStart(2, "0")}
          </span>
          <span className="cap-dock-track">
            <i style={{ transform: `scaleX(${railProgress})` }} />
          </span>
        </div>
      </div>

      {devMode&&<DevBadge id="what-i-do" devMode={devMode} theme={theme}/>}
    </section>

    {/* EXPERTISE — bento mosaic */}
    <section ref={skillsRef} id="skills" className="skills-section light-section-shell section-skills expertise-section">
      <div className="expertise-inner">
        <div className="expertise-header">
          <span className="expertise-eyebrow">Expertise</span>
          <h2 className="section-title expertise-title">Skills & Stack</h2>
          <p className="expertise-lead">Design craft and engineering depth — measured in practice, not buzzwords.</p>
        </div>
        <div className="expertise-layout">
          <aside className="expertise-skills-rail">
            <span className="expertise-rail-label">Proficiency</span>
            <ul className="expertise-skill-list">
              {SKILLS.map((s, i) => (
                <li key={s.label} className="expertise-skill-row">
                  <div className="expertise-skill-head">
                    <span className="expertise-skill-name">{s.label}</span>
                    <span className="expertise-skill-pct">{s.pct}%</span>
                  </div>
                  <div className="expertise-meter" aria-hidden="true">
                    <div className="expertise-meter-fill" style={{ width: `${s.pct}%` }} />
                  </div>
                </li>
              ))}
            </ul>
          </aside>

          <div className="expertise-tech-arena">
            <div className="expertise-tech-orbit" aria-hidden="true" />
            <div className="expertise-tech-header">
              <div>
                <span className="expertise-tech-eyebrow">Tech Stack</span>
                <h3 className="expertise-tech-title">Tools I build with</h3>
              </div>
              <span className="expertise-tech-count">{TECH.length} technologies</span>
            </div>
            <div className="expertise-stack-constellation">
              {TECH.map((t) => {
                const isSpotlight = ["React", "TypeScript", "GSAP", "Figma"].includes(t.name);
                return (
                  <div key={t.name} className={`expertise-stack-tile${isSpotlight ? " is-spotlight" : ""}`}>
                    <img src={t.colorLogo} alt="" width={isSpotlight ? 44 : 32} height={isSpotlight ? 44 : 32} loading="lazy" />
                    <span>{t.name}</span>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
      {devMode && <DevBadge id="skills" devMode={devMode} theme={theme} />}
    </section>

    {/* PROJECTS — large case study cards */}
    <section ref={projectsRef} id="projects" className="projects-section light-section-shell section-projects" style={{padding:"100px 60px",position:"relative"}}>
      <div style={{maxWidth:1320,margin:"0 auto"}}>
        <div className="sec-head">
          <span className="sec-eyebrow">Selected work</span>
          <h2 className="section-title">Featured Work</h2>
          <p className="sec-lead">A selection of enterprise engagements — from greenfield architecture to complex systems integration at scale.</p>
        </div>
        <div className="work-grid">
          {PROJECTS.map((p)=>(
            <article className="work-card" key={p.id}>
              {p.liveUrl && (
                <a
                  className="work-shot"
                  href={p.liveUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={`Open the ${p.title} live site`}
                >
                  <span
                    className="work-shot-img"
                    style={{backgroundImage:p.image?`url(${p.image})`:p.cardBg}}
                  />
                  <span className="work-shot-badge"><i />Live</span>
                  <span className="work-shot-open">View site →</span>
                </a>
              )}
              <div className="work-body">
                <div className="work-meta">
                  <span className="work-index">{String(p.id).padStart(2,"0")}</span>
                  <span className="work-meta-rule" />
                  <span className="work-category">{p.category}</span>
                </div>
                <h3 className="work-title">{p.title}</h3>
                <p className="work-desc">{p.longDesc}</p>
                <ul className="work-stack">
                  {p.stack.map((tech)=><li key={tech}>{tech}</li>)}
                </ul>
                <dl className="work-facts">
                  <div><dt>Year</dt><dd>{p.year}</dd></div>
                  <div><dt>Role</dt><dd>Design &amp; build</dd></div>
                  <div><dt>Outcome</dt><dd>{p.outcome}</dd></div>
                </dl>
              </div>
            </article>
          ))}
        </div>
      </div>
      {devMode&&<DevBadge id="projects" devMode={devMode} theme={theme}/>}
    </section>

    {/* EXPRESSION — the working type & colour system, shown as a spec sheet */}
    <section ref={typeCanvasRef} id="type-canvas" className="typeset-section light-section-shell section-type-canvas">
      <div className="typeset-inner">
        <div className="sec-head">
          <span className="sec-eyebrow">Expression</span>
          <h2 className="section-title">Type &amp; Colour</h2>
          <p className="sec-lead">
            The system underneath the work. A type scale that carries hierarchy without shouting,
            and palettes built for contrast first and decoration second.
          </p>
        </div>

        <div className="typeset-grid">
          <section className="typeset-panel typeset-panel-type" aria-labelledby="typeset-type-h">
            <header className="typeset-panel-head">
              <h3 id="typeset-type-h">Typefaces</h3>
              <span>{String(TYPEFACES.length).padStart(2, "0")} families</span>
            </header>
            <ul className="typeset-list">
              {TYPEFACES.map((t) => (
                <li className="typeset-row" key={t.name}>
                  <span
                    className="typeset-glyph"
                    style={{ fontFamily: t.font, fontWeight: t.weight, fontStyle: t.italic ? "italic" : "normal" }}
                  >
                    Aa
                  </span>
                  <span className="typeset-id">
                    <strong>{t.name}</strong>
                    <em>{t.role}</em>
                    <span className="typeset-note">{t.note}</span>
                  </span>
                  <span
                    className="typeset-sample"
                    style={{ fontFamily: t.font, fontWeight: t.weight, fontStyle: t.italic ? "italic" : "normal" }}
                  >
                    {t.sample}
                  </span>
                  <span className="typeset-weight">{t.weight}</span>
                </li>
              ))}
            </ul>
          </section>

          <section className="typeset-panel typeset-panel-colour" aria-labelledby="typeset-colour-h">
            <header className="typeset-panel-head">
              <h3 id="typeset-colour-h">Palettes</h3>
              <span>Ratios vs. page background</span>
            </header>
            <div className="palette-grid">
              {PALETTES.map((p) => (
                <article className="palette-card" key={p.name}>
                  <header className="palette-card-head">
                    <h4>{p.name}</h4>
                    <span>{p.use}</span>
                  </header>
                  <ol className="palette-ramp">
                    {p.steps.map((c) => (
                      <li className="palette-chip" key={c.hex}>
                        <span className="palette-swatch" style={{ background: c.hex }} />
                        <span className="palette-step">{c.step}</span>
                        <span className="palette-role">{c.role}</span>
                        <code className="palette-hex">{c.hex}</code>
                        <span className="palette-ratio">{c.ratio ? `${c.ratio}:1` : "—"}</span>
                        <span className={`palette-grade${c.grade ? "" : " is-surface"}`}>
                          {c.grade || "Surface"}
                        </span>
                      </li>
                    ))}
                  </ol>
                </article>
              ))}
            </div>
            <p className="typeset-footnote">
              Contrast measured with the WCAG 2.1 relative-luminance formula against <code>#F2EFE7</code>.
              Steps 300 and 100 are surface tones and carry no text.
            </p>
          </section>
        </div>
      </div>

      {devMode && <DevBadge id="type-canvas" devMode={devMode} theme={theme} />}
    </section>

    {/* CONTACT — combined connect and form in creative split layout */}
    <section ref={contactRef} id="contact" className="contact-section light-section-shell section-contact" style={{position:"relative"}}>
      <div style={{maxWidth:1200,margin:"0 auto"}}>
        <div className="sec-head sec-head-center">
          <span className="sec-eyebrow">Connect</span>
          <h2 className="section-title">Let's Work Together</h2>
        </div>
        {/* Creative split layout */}
        <div className="contact-split-layout">
          {/* Left side - Contact info cards */}
          <div className="contact-cards">
            <p className="contact-intro">I'm always interested in hearing about new projects and opportunities. Whether you have a question or just want to say hi, feel free to reach out!</p>
            <div className="contact-card-stack">
              {CONTACT_INFO.map((c,i)=>(
                <a key={i} href={c.link} target="_blank" rel="noopener noreferrer" className="contact-info-card">
                  <span className="contact-info-icon">{c.icon}</span>
                  <span className="contact-info-copy">
                    <span className="contact-info-title">{c.title}</span>
                    <span className="contact-info-value" title={c.value}>{c.value}</span>
                  </span>
                  <span className="contact-info-arrow" aria-hidden="true">→</span>
                </a>
              ))}
            </div>
          </div>

          {/* Right side - Contact form */}
          <div className="contact-form">
            <div className="contact-form-panel">
              {sent?<div className="contact-sent"><div className="contact-sent-mark">✓</div><h3>Message Sent!</h3><p>Michael will reply shortly.</p></div>:<>
                {[{l:"Name",k:"name",t:"text",p:"Your name"},{l:"Email",k:"email",t:"email",p:"hello@example.com"},{l:"Subject",k:"subject",t:"text",p:"Project Inquiry"}].map(f=><div key={f.k} className="contact-field">
                  <label htmlFor={`contact-${f.k}`}>{f.l}</label>
                  <input id={`contact-${f.k}`} type={f.t} placeholder={f.p} value={form[f.k]} onChange={e=>setForm(d=>({...d,[f.k]:e.target.value}))}/>
                </div>)}
                <div className="contact-field">
                  <label htmlFor="contact-message">Message</label>
                  <textarea id="contact-message" rows={5} placeholder="Tell me about your project..." value={form.message} onChange={e=>setForm(d=>({...d,message:e.target.value}))}/>
                </div>
                <button className="bp contact-submit" onClick={()=>{
                  const subject = encodeURIComponent(form.subject || "Portfolio Contact");
                  const body = encodeURIComponent(`Name: ${form.name}\nEmail: ${form.email}\n\n${form.message}`);
                  window.open(`mailto:michaelgaitho47@gmail.com?subject=${subject}&body=${body}`);
                  setSent(true);
                }}>Send Message →</button>
              </>}
            </div>
          </div>
        </div>
      </div>
      {devMode&&<DevBadge id="contact" devMode={devMode} theme={theme}/>}
    </section>
    </div>
    </>;
}
